mapper.sql:
FROM raw_attendance_records r
LEFT JOIN employee e ON r.account = e.account and e.id != 1
WHERE 1=1

    AND r.account = #{account}


    AND date_time >= #{startDate}


    AND date_time <= #{endDate}

mapper.select:
SELECT r.account, MIN(date_time) as firstCheckInTime, MAX(date_time) as lastCheckOutTime
FROM raw_attendance_records r LEFT JOIN employee e ON r.account = e.account and e.id != 1
WHERE r.date_time between #{startDate} and #{endDate} and e.id = #{employeeId}
